"""Durable original files; paths are generated by the server, never the model."""
import base64
import hashlib
from pathlib import Path

from orchestrator_bot.supplier_catalog import _immutable


def save_original(state_dir, data, filename, parsed):
    digest = hashlib.sha256(data).hexdigest()
    suffix = Path(filename).suffix.lower()
    folder = Path(state_dir).resolve() / 'documents'
    folder.mkdir(parents=True, exist_ok=True)
    _immutable(folder / (digest + suffix), data)
    return {'filename': filename[:512], 'sha256': digest, 'extension': suffix,
            'text': parsed['text'], 'metadata': parsed['metadata']}


def original_bundle(state_dir, document):
    import re
    from orchestrator_bot.document_import import MAX_FILE_BYTES, SUPPORTED_EXTENSIONS
    digest, suffix = document['sha256'], document['extension']
    if not re.fullmatch('[a-f0-9]{64}', digest) or suffix not in SUPPORTED_EXTENSIONS:
        raise ValueError('Повреждена ссылка на исходный документ')
    path = Path(state_dir).resolve() / 'documents' / (digest + suffix)
    if path.stat().st_size > MAX_FILE_BYTES:
        raise ValueError('Исходный документ больше лимита')
    data = path.read_bytes()
    if hashlib.sha256(data).hexdigest() != digest:
        raise ValueError('Исходный документ изменился; отправьте заново')
    return {**document, 'data': base64.b64encode(data).decode('ascii')}
